package com.pixilife.android;
import android.content.*;import android.database.sqlite.SQLiteDatabase;import android.os.*;import java.util.*;import java.util.regex.*;
public class PersonalCommandReceiver extends BroadcastReceiver {
 private static long token;@Override public void onReceive(Context c,Intent i){if(!"heard".equals(i.getStringExtra("type")))return;String q=i.getStringExtra("value");if(q==null)return;long mine=++token;new Handler(Looper.getMainLooper()).postDelayed(()->{if(mine==token)process(c.getApplicationContext(),q);},1900);}
 private void process(Context c,String q){String t=q.toLowerCase(Locale.ROOT);android.content.SharedPreferences p=c.getSharedPreferences("relationship",Context.MODE_PRIVATE);long now=System.currentTimeMillis();p.edit().putLong("last_interaction",now).putLong("first_interaction",p.getLong("first_interaction",now)).putInt("interactions",p.getInt("interactions",0)+1).apply();if(t.startsWith("agrega ")||t.startsWith("añade ")){String task=q.replaceFirst("(?i)^(agrega|añade)\\s+","").trim();android.content.ContentValues v=new android.content.ContentValues();v.put("text",task);v.put("done",0);v.put("created_at",now);v.put("updated_at",now);new MemoryDatabase(c).getWritableDatabase().insert("tasks",null,v);}if(t.contains("recuérdame")||t.contains("recuerdame")){Matcher m=Pattern.compile("(?:a las?|en)\\s*(\\d{1,2})(?::(\\d{2}))?").matcher(t);if(m.find()){int h=Integer.parseInt(m.group(1)),min=m.group(2)==null?0:Integer.parseInt(m.group(2));Calendar at=Calendar.getInstance();at.set(Calendar.HOUR_OF_DAY,h);at.set(Calendar.MINUTE,min);at.set(Calendar.SECOND,0);if(at.before(Calendar.getInstance()))at.add(Calendar.DAY_OF_YEAR,1);android.content.ContentValues v=new android.content.ContentValues();v.put("text",q);v.put("due_at",at.getTimeInMillis());v.put("repeat_rule","");v.put("status","pending");v.put("created_at",now);long id=new MemoryDatabase(c).getWritableDatabase().insert("reminders",null,v);AlarmReceiver.scheduleAt(c,(int)id+50000,at.getTimeInMillis(),q);}}}
}
